  const f=await authenticatedInstructionFixture(),p=await f.issue(),credential='av3ex1_'+'s'.repeat(43);let lookups=0,scopeChanged=false;
  const unused=async()=>assert.fail('SEND_ROUTE_MUST_NOT_CALL_OTHER_CONSUMER');
