  const raw={method:'POST',path:p.proof.path,query:[],bodyRaw:p.raw,cookie:null,credential,challengeRef:p.issued.ref,proof:p.proof,signature:p.signature};
  for(const invalid of [{...raw,cookie:'synthetic-cookie'},{...raw,credential:'av3er1_'+'s'.repeat(43)}])await assert.rejects(router.handle(invalid),/EXECUTION_REQUEST_REJECTED/);
  assert.equal(lookups,0);assert.equal(f.state().permits.length,0);
